import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * INTEREST RUN
 * CHG 17.01.2001 - rounding added after complaint from branch 0042
 * CHG 2024 - migrated to BigDecimal for precision
 */
public class InterestCalculator {

    public BigDecimal monthlyInterest(BigDecimal balance, BigDecimal annualRatePercent) {
        // interest = balance * annualRatePercent / 100 / 12
        return balance.multiply(annualRatePercent)
                .divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP)
                .divide(new BigDecimal("12"), 10, RoundingMode.HALF_UP)
                .setScale(2, RoundingMode.HALF_UP);
    }
}

