package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

/**
 * SPLIT PAYMENTS (standing orders to several payees)
 */
public class PaymentSplitter {

    /** Splits total amount into shares, handling remainder cents. */
    public List<BigDecimal> split(BigDecimal total, int payees) {
        BigDecimal totalCents = total.movePointRight(2).setScale(0, RoundingMode.HALF_UP);
        long totalCentsLong = totalCents.longValue();
        long shareCents = totalCentsLong / payees;
        long remainder = totalCentsLong % payees;

        List<BigDecimal> shares = new ArrayList<>();
        for (int i = 0; i < payees; i++) {
            long cents = shareCents + (i < remainder ? 1 : 0);
            shares.add(BigDecimal.valueOf(cents).movePointLeft(2));
        }
        return shares;
    }
}
